// AWI: update TiTAN brosur tahap 2 - sekali jalan (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/tfix2', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$out = array();
			$m = array(10700 => 10847, 10696 => 10856, 10697 => 10849, 10698 => 10858, 10699 => 10852, 10701 => 10851, 10702 => 10857, 10703 => 10848, 10704 => 10855, 10705 => 10850);
			foreach ($m as $a => $b) {
				$rows = $wpdb->get_col($wpdb->prepare("SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key IN ('_thumbnail_id','_yoast_wpseo_opengraph-image-id','_yoast_wpseo_twitter-image-id') AND meta_value=%s", (string) $a));
				foreach ($rows as $pid) { $wpdb->query($wpdb->prepare("UPDATE {$wpdb->postmeta} SET meta_value=%s WHERE post_id=%d AND meta_value=%s AND meta_key IN ('_thumbnail_id','_yoast_wpseo_opengraph-image-id','_yoast_wpseo_twitter-image-id')", (string) $b, $pid, (string) $a)); clean_post_cache($pid); $out['thumb'][] = $pid . ':' . $a . '>' . $b; }
			}
			$og = $wpdb->get_results("SELECT post_id, meta_key, meta_value FROM {$wpdb->postmeta} WHERE meta_key IN ('_yoast_wpseo_opengraph-image','_yoast_wpseo_twitter-image') AND meta_value LIKE '%byd-ti7-%'");
			foreach ($og as $r) { update_post_meta($r->post_id, $r->meta_key, wp_get_attachment_url(10847)); $out['og'][] = $r->post_id; }
			$c = get_post_field('post_content', 10818); $o = $c;
			$c = preg_replace('#Pilihan warna global TiTAN 7 DM:.*?dikonfirmasi saat peluncuran\.#s', 'Pilihan warna resmi BYD TiTAN 7 DM di Indonesia: <strong>Ti Grey</strong>, <strong>Cosmos Black</strong>, dan <strong>Nebula Silver</strong>, dengan interior Blue + Black.', $c);
			if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => 10818)); clean_post_cache(10818); }
			$out['article'] = array('changed' => $c !== $o, 'bad' => preg_match_all('/Jade Green|Starlight|Obsidian|Mountain Green|Titanium Grey/', $c));
			if (function_exists('YoastSEO')) { $out['yoast'] = 'present'; }
			wp_cache_flush();
			return $out;
		},
	));
});
